/*!
 * godark-chart — minimal line chart stub for the godark dashboard.
 * NOT Chart.js. Maps {x: ISO-8601, y: number} datasets to a canvas using
 * linear timestamp scaling on the x-axis.
 */
(function(global,factory){typeof exports==='object'&&typeof module!=='undefined'?module.exports=factory():typeof define==='function'&&define.amd?define(factory):(global=typeof globalThis!=='undefined'?globalThis:global||self,global.Chart=factory())})(this,function(){'use strict';

var defaults={animation:{duration:400},responsive:true,maintainAspectRatio:true,plugins:{legend:{display:true},tooltip:{enabled:true}}};

function merge(target,src){if(!src)return target;for(var k in src){if(Object.prototype.hasOwnProperty.call(src,k)){if(typeof src[k]==='object'&&src[k]!==null&&!Array.isArray(src[k])){target[k]=target[k]||{};merge(target[k],src[k])}else{target[k]=src[k]}}}return target}

function Chart(ctx,config){
  this.ctx=typeof ctx==='string'?document.getElementById(ctx):ctx;
  this.config=merge(merge({},defaults),config||{});
  this._data=this.config.data||{datasets:[]};
  this._type=this.config.type||'line';
  this._canvas=this.ctx&&this.ctx.canvas?this.ctx.canvas:this.ctx;
  if(this._canvas&&this._canvas.getContext){
    var c=this._canvas.getContext('2d');
    if(c){this._render(c)}
  }
}

Chart.prototype._render=function(ctx){
  var w=this._canvas.width||300;
  var h=this._canvas.height||150;
  ctx.clearRect(0,0,w,h);
  ctx.fillStyle='#f8fafc';
  ctx.fillRect(0,0,w,h);
  ctx.strokeStyle='#e2e8f0';
  ctx.lineWidth=1;
  ctx.strokeRect(0,0,w,h);
  var datasets=this._data.datasets||[];
  var colors=['#4ade80','#f59e0b','#60a5fa','#f87171','#a78bfa'];
  for(var di=0;di<datasets.length;di++){
    var ds=datasets[di];
    var pts=ds.data||[];
    if(pts.length===0)continue;
    ctx.beginPath();
    ctx.strokeStyle=ds.borderColor||colors[di%colors.length];
    ctx.lineWidth=2;
    var padX=40,padY=20;
    var plotW=w-padX*2,plotH=h-padY*2;
    var ys=pts.map(function(p){return typeof p==='object'?p.y:p});
    var minY=Math.min.apply(null,ys),maxY=Math.max.apply(null,ys);
    var rangeY=maxY-minY||1;
    // Parse x values as timestamps for linear time scaling.
    var ts=pts.map(function(p){return typeof p==='object'&&p.x!=null?Date.parse(p.x):0});
    var minT=Math.min.apply(null,ts),maxT=Math.max.apply(null,ts);
    var rangeT=maxT-minT||1;
    for(var i=0;i<pts.length;i++){
      var y=typeof pts[i]==='object'?pts[i].y:pts[i];
      var px=padX+((ts[i]-minT)/rangeT)*plotW;
      var py=padY+plotH-(y-minY)/rangeY*plotH;
      if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
    }
    ctx.stroke();
    if(ds.fill){
      ctx.lineTo(padX+plotW,padY+plotH);
      ctx.lineTo(padX,padY+plotH);
      ctx.closePath();
      ctx.fillStyle=(ds.backgroundColor||colors[di%colors.length]+'22');
      ctx.fill();
    }
    ctx.fillStyle=ds.borderColor||colors[di%colors.length];
    for(var j=0;j<pts.length;j++){
      var yj=typeof pts[j]==='object'?pts[j].y:pts[j];
      var pxj=padX+((ts[j]-minT)/rangeT)*plotW;
      var pyj=padY+plotH-(yj-minY)/rangeY*plotH;
      ctx.beginPath();
      ctx.arc(pxj,pyj,3,0,Math.PI*2);
      ctx.fill();
    }
  }
};

Chart.prototype.destroy=function(){};
Chart.prototype.update=function(){if(this._canvas&&this._canvas.getContext){this._render(this._canvas.getContext('2d'))}};
Chart.prototype.resize=function(){this.update()};

Chart.register=function(){};
Chart.defaults=defaults;

return Chart;
});
